library EnumLib {
    pure fn head_doubled(xs: Vec<u32>, limit: u32) -> Vec<u32> {
        xs.enumerate()
            .filter(|(_, x)| *x > 0)
            .take(limit)
            .map(|(_, x)| *x * 2)
            .collect()
    }
}

